func (s *Service) ProcessLog(...) error {
    if depositLog.Topics[0] == depositEventSignature { // Layer 1: topic filter
        return s.ProcessDepositLog(ctx, depositLog)
    }
    return nil
}
func (s *Service) ProcessDepositLog(...) error {
    index := int64(binary.LittleEndian.Uint64(merkleTreeIndex))
    if index <= s.lastReceivedMerkleIndex { return nil } // Layer 2: dedup
    if index != s.lastReceivedMerkleIndex+1 { return error } // Layer 2: sequence
    ...
}

func UnpackDepositLogData(data []byte) (pubkey, withdrawalCredentials, amount, signature, index []byte, err error) {
    contractAbi, err := abi.JSON(bytes.NewReader([]byte(DepositContractABI)))
    unpackedLogs, err := contractAbi.Unpack("DepositEvent", data)
    if err != nil { return ..., errors.Wrap(err, "unable to unpack logs") }
    return unpackedLogs[0].([]byte), ...
    // NOTE: No explicit per-field length check after unpack
}

func (s *Service) notifyNewPayload(...) (bool, error) {
    if blk.Version() >= version.Electra {
        requests, err = blk.Block().Body().ExecutionRequests()
        if requests == nil { return false, errors.New("nil execution requests") }
    }
    // Prysm passes requests to EL via engine_newPayloadV4
    // EL computes requests_hash; Prysm has no compute_requests_hash implementation
    lastValidHash, err = s.cfg.ExecutionEngineCaller.NewPayload(ctx, payload, versionedHashes, parentRoot, requests)
}
